const data={
'electric-tractor-selection':{label:'MODEL GUIDE',date:'September 7, 2026',time:'8 min read',title:'How to Select a Dongfeng Electric Tractor for Port and Regional Haulage',intro:'The right electric tractor is selected from the route backward—not from battery size alone. Start with gross combination weight, daily distance, grade, charging windows and destination-market interface.',image:'assets/tractor.jpg',sections:[['1. Define the actual transport cycle','Record loaded and empty distance, average and maximum speed, road grade, waiting time, shifts per day and the available charging window. Port shuttles with predictable pauses need a different configuration from continuous regional transport.'],['2. Match the GCW class','The catalogue lists TE46 / TE4Z at 42 t GCW, TE8L / TE8K and TE9L at 49 t, TE9B at 65 t, TE8M at 80 t and TE8P up to 120 t. Select the weight class first, then refine battery and axle specification.'],['3. Select battery capacity around usable energy','Listed CATL choices across the TE range include 400, 466, 497 and 600 kWh. A larger battery may extend operating time, but it also affects vehicle weight, cost and charging demand.'],['4. Confirm charging and market requirements','Selected tractor models list dual-gun charging at 500 or 600 A. TE4Z and TE8K are catalogue-listed with European interfaces, while other variants use the Chinese standard.'],['5. Review power and safety','LvKong systems range from 315 / 510 kW to 400 / 550 kW across listed models. EBS, ESC, LDWS and FCWS are included on the referenced tractor configurations.']]},
'electric-dump-truck-guide':{label:'APPLICATION GUIDE',date:'September 7, 2026',time:'7 min read',title:'Electric Dump Trucks for Mining and Construction: What Buyers Should Check',intro:'Mining and construction trucks operate under high payload, steep grades, dust, heat and repetitive cycles. These conditions must drive the specification.',image:'assets/dumper.jpg',sections:[['1. Separate urban construction from mine haulage','KTA1 is a 31 t 8×4 construction platform. TZ3Z / TZ4Y cover the 55 t class, while TZ5E, TZ3V and TZ5Y extend to 65–80 t heavy-duty work.'],['2. Check grade and payload together','Motor output, axle capacity, tyre selection and frame structure must support the loaded uphill section and repeated braking on descent.'],['3. Build charging into the shift plan','Selected heavy models list 400 or 600 kWh CATL packs and dual-gun 600 A charging. Actual time depends on charger, temperature and battery conditions.'],['4. Confirm steering and interface','TZ4Y and TZ5Y are right-hand-drive variants. TZ4Y is listed with a European charging interface.'],['5. Specify the body and hydraulics','Send body volume, material density, floor and side thickness, tipping method and cycle frequency. The complete vehicle should be engineered as one system.']]},
'ev-truck-range-tco':{label:'TCO & CHARGING',date:'September 7, 2026',time:'6 min read',title:'How Duty Cycle Affects Electric Truck Range and Total Cost',intro:'A useful electric-truck business case is based on cost per completed transport task, not only on the catalogue range or purchase price.',image:'assets/cargo.jpg',sections:[['1. Range is an operating result','Payload, average speed, road grade, temperature, traffic, auxiliary power and driver behavior all change consumption.'],['2. Calculate usable daily energy','Estimate loaded and empty consumption, add body and climate loads, then keep a practical reserve.'],['3. Charging time has an economic value','A smaller battery with reliable opportunity charging may outperform a larger pack that carries extra weight.'],['4. Include the whole fleet system','TCO should include vehicle purchase, electricity, charger and installation, driver time, maintenance, tyres, battery terms and lost productivity.'],['5. Use route data before ordering','Provide country, route distance, payload, road speed, maximum grade, shifts, temperature range and charging standard.']]}}
const id=new URLSearchParams(location.search).get('id')||'electric-tractor-selection',a=data[id]||data['electric-tractor-selection'];document.title=a.title+' | Dongfeng EV Blog';document.querySelector('meta[name="description"]').content=a.intro;document.querySelector('#article').innerHTML=`<article class="article-page"><a class="back" href="blog.html">← Back to Blog</a><header><p class="blog-meta">${a.label} · ${a.date} · ${a.time}</p><h1>${a.title}</h1><p>${a.intro}</p></header><img class="article-hero-image" src="${a.image}" alt="${a.title}"><div class="article-body">${a.sections.map(s=>`<section><h2>${s[0]}</h2><p>${s[1]}</p></section>`).join('')}<aside><strong>Important:</strong> Published figures are reference configurations from the supplied Dongfeng catalogue. Final specification, compliance and performance must be confirmed for the destination and duty cycle.</aside></div></article>`;
